#define T1_NOF_FLEX_STPWS_CORE2                       (16u)
#define T1_NOF_STPWS_CORE2                            (T1_NOF_USER_STPWS_CORE2 + T1_NOF_FLEX_STPWS_CORE2)
#define T1_NOF_FLEX_ADDRS_CORE2                       (16u)
#define T1_NOF_FLEXBUFFER_ENTRIES_CORE2               (1u)
#define T1_OUTER_HANDLER_CORE2                        (T1_OuterHandlerCore2)
#define T1_PTIMER_CORE2                               (0xFC068004uL)
#define T1_SYNC_PERIOD_CORE2                          (10u)
#define T1_GET_RAW_TIME_CORE2( )                      (*(T1_tickUint_t volatile const *)T1_PTIMER_CORE2)
#define T1_TRACE_TIMER_IS_SYNC_TIMER_CORE2            (1)
#define T1_TRACE_TIMER_COUNTS_DOWN_CORE2              (T1_FALSE)
#define T1_TRACE_TIMER_BIT_LENGTH_CORE2               (29u)
