/* Unused cores. */
#define T1_TRACE_TIMER_IS_SYNC_TIMER_CORE3            (1)
#define T1_TRACE_TIMER_IS_SYNC_TIMER_CORE4            (1)
#define T1_TRACE_TIMER_IS_SYNC_TIMER_CORE5            (1)


#if ! defined T1_CORE_ID_TO_SCOPE_CONSTS
#   if ! defined T1_CLONE
/* This default version can be evaluated at compile time when passed a literal input */
#       if 2 < T1_NOF_CORES && defined __GNUC__ /* use switch statement */
#           define T1_CORE_ID_TO_SCOPE_CONSTS( coreId_ ) ({                 \
    T1_scopeConsts_t * pScopeConsts_;                                       \
    switch( coreId_ )                                                       \
    {                                                                       \
    case 0:     pScopeConsts_  = T1_P_SCOPE_CONSTS0;    break;              \
    case 1:     pScopeConsts_  = T1_P_SCOPE_CONSTS1;    break;              \
    default:    pScopeConsts_  = T1_P_SCOPE_CONSTS2;    break;              \
    }                                                                       \
    pScopeConsts_;                                                          \
})
#           define T1_CORE_ID_TO_SCOPE_FG_CONSTS( coreId_ ) ({              \
    T1_scopeFgConsts_t * pScopeFgConsts_;                                   \
    switch( coreId_ )                                                       \
    {                                                                       \
    case 0:     pScopeFgConsts_  = T1_P_SCOPE_FG_CONSTS0;    break;         \
    case 1:     pScopeFgConsts_  = T1_P_SCOPE_FG_CONSTS1;    break;         \
    default:    pScopeFgConsts_  = T1_P_SCOPE_FG_CONSTS2;    break;         \
    }                                                                       \
    pScopeFgConsts_;                                                        \
})
#       else /* NOTE 'coreId_' can be evaluated more than once with >2 cores */
#           define T1_CORE_ID_TO_SCOPE_CONSTS( coreId_ ) (                  \
    ( 0 == (coreId_) ) ? T1_P_SCOPE_CONSTS0   :                             \
    ( 1 == (coreId_) ) ? T1_P_SCOPE_CONSTS1   :                             \
                         T1_P_SCOPE_CONSTS2                                 \
)
#           define T1_CORE_ID_TO_SCOPE_FG_CONSTS( coreId_ ) (               \
    ( 0 == (coreId_) ) ? T1_P_SCOPE_FG_CONSTS0  :                           \
    ( 1 == (coreId_) ) ? T1_P_SCOPE_FG_CONSTS1  :                           \
                         T1_P_SCOPE_FG_CONSTS2                              \
)
#       endif /* switch or ?: */
#   endif /* ! defined T1_CLONE */
#endif /* ! defined T1_CORE_ID_TO_SCOPE_CONSTS */

#if ! defined T1_CONT_RC_UNMAP
#   define T1_CONT_RC_UNMAP( coreId_ )                (coreId_)
#endif /* ! defined T1_CONT_RC_UNMAP */

#define T1_TRACE_TASK( taskId_ ) \
(  1 \
 && ((taskId_) != T1_Idle_Task_Core0_ID) \
 && ((taskId_) != T1_Idle_Task_Core1_ID) \
 && ((taskId_) != T1_Idle_Task_Core2_ID) \
)


